def cot_prompt(question, steps_hint="Think step by step."):
    return f"{steps_hint}\n\nQuestion: {question}\nAnswer:"

def few_shot_prompt(examples, question):
    lines = []
    for q, a in examples:
        lines.append(f"Q: {q}\nA: {a}")
    lines.append(f"Q: {question}\nA:")
    return "\n\n".join(lines)

cot = cot_prompt("What is 17 * 13?")
few = few_shot_prompt(
    [("What is 2 * 3?", "6"), ("What is 4 * 5?", "20")],
    "What is 6 * 7?"
)
print(cot)
print("---")
print(few)
